#include <cstddef>
#include <vector>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    double product = 1.0;
    const long long n = static_cast<long long>(x.size());

    #pragma omp parallel for default(none) shared(x, n) reduction(* : product)
    for (long long i = 0; i < n; ++i) {
        const double v = x[static_cast<std::size_t>(i)];
        product *= ((i & 1LL) == 0) ? v : (1.0 / v);
    }

    return product;
}
